<script setup>
import GuestLayout from '@/Layouts/GuestLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { gsap } from 'gsap';
import { onBeforeUnmount, onMounted, ref } from 'vue';
defineProps({ canResetPassword:Boolean, status:String });
const form=useForm({email:'',password:'',remember:false});
const formRoot=ref(null);const showPassword=ref(false);let animationContext;
const submit=()=>form.post(route('login'),{onFinish:()=>form.reset('password')});
onMounted(()=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;animationContext=gsap.context(()=>{gsap.timeline({defaults:{ease:'power3.out'}}).from('.login-kicker',{x:-20,opacity:0,duration:.45}).from('.login-title span',{y:30,opacity:0,stagger:.1,duration:.58},'-=.2').from('.login-copy',{y:15,opacity:0,duration:.4},'-=.25').from('.field, .form-options',{y:18,opacity:0,stagger:.07,duration:.42},'-=.18').from('.login-button',{y:18,duration:.35,clearProps:'transform'},'-=.18')},formRoot.value)});onBeforeUnmount(()=>animationContext?.revert());
</script>

<template><GuestLayout><Head title="Masuk"/><div ref="formRoot" class="login-form"><div class="login-kicker">Portal COSMIC</div><h2 class="login-title"><span>Welcome</span> <span>Back.</span></h2><p class="login-copy">Masuk untuk mengakses dashboard dan mengelola website COSMIC.</p><div v-if="status" class="status-message">{{status}}</div>
<form @submit.prevent="submit"><div class="field"><label for="email">Email</label><div class="input-wrap"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M4 6h16v12H4zM4 7l8 6 8-6"/></svg><input id="email" v-model="form.email" type="email" placeholder="admin@cosmic.id" required autofocus autocomplete="username"/></div><p v-if="form.errors.email" class="input-error">{{form.errors.email}}</p></div>
<div class="field"><label for="password">Password</label><div class="input-wrap"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg><input id="password" v-model="form.password" :type="showPassword?'text':'password'" placeholder="Masukkan password" required autocomplete="current-password"/><button class="password-toggle" type="button" :aria-label="showPassword?'Sembunyikan password':'Tampilkan password'" @click="showPassword=!showPassword">{{showPassword?'Hide':'Show'}}</button></div><p v-if="form.errors.password" class="input-error">{{form.errors.password}}</p></div>
<div class="form-options"><label class="remember"><input v-model="form.remember" type="checkbox"/><span></span>Ingat saya</label><Link v-if="canResetPassword" :href="route('password.request')">Lupa password?</Link></div><button class="login-button" type="submit" :disabled="form.processing"><span>{{form.processing?'Memproses...':'Masuk ke Dashboard'}}</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M5 12h14M13 6l6 6-6 6"/></svg></button></form><p class="security-note"><span></span>Secure member access</p></div></GuestLayout></template>

<style scoped>
.login-kicker{color:var(--color-accent);font:800 .63rem var(--font-display);letter-spacing:.19em;text-transform:uppercase}.login-title{margin:10px 0 0;font:900 clamp(3.3rem,5vw,4.7rem)/.82 var(--font-display);letter-spacing:-.045em;text-transform:uppercase}.login-title span:last-child{color:var(--color-accent)}.login-copy{margin:14px 0 28px;color:#9fadb9;font-size:.76rem;line-height:1.6}.status-message{margin-bottom:18px;padding:11px 13px;border-left:2px solid var(--color-accent);color:#bfe5ff;background:rgba(69,183,255,.08);font-size:.75rem}.field+.field{margin-top:18px}.field label{display:block;margin-bottom:8px;color:#c8d2da;font:750 .62rem var(--font-display);letter-spacing:.13em;text-transform:uppercase}.input-wrap{position:relative;display:flex;align-items:center}.input-wrap>svg{position:absolute;left:14px;width:18px;color:#718492;stroke-width:1.6;pointer-events:none}.input-wrap input{width:100%;height:50px;padding:0 70px 0 43px;border:1px solid rgba(175,218,255,.2);border-radius:4px;outline:0;color:white;background:rgba(255,255,255,.025);font:500 .82rem var(--font-body);transition:.2s}.input-wrap input::placeholder{color:#667582}.input-wrap input:focus{border-color:var(--color-accent);background:rgba(69,183,255,.045);box-shadow:0 0 0 3px rgba(69,183,255,.08)}.password-toggle{position:absolute;right:13px;border:0;color:#8d9ca8;background:transparent;font:750 .56rem var(--font-display);letter-spacing:.1em;text-transform:uppercase;cursor:pointer}.password-toggle:hover{color:var(--color-accent)}.input-error{margin:7px 0 0;color:#ff8b93;font-size:.68rem}.form-options{display:flex;align-items:center;justify-content:space-between;gap:15px;margin:18px 0 23px}.remember{display:flex;align-items:center;gap:8px;color:#95a3af;font-size:.68rem;cursor:pointer}.remember input{position:absolute;opacity:0}.remember span{display:grid;width:16px;height:16px;place-items:center;border:1px solid rgba(255,255,255,.3);border-radius:3px}.remember input:checked+span{border-color:var(--color-accent);background:var(--color-accent)}.remember input:checked+span::after{content:'✓';color:#04101c;font-size:.7rem;font-weight:900}.form-options a{color:#aebac4;font:700 .6rem var(--font-display);letter-spacing:.08em;text-decoration:none;text-transform:uppercase}.form-options a:hover{color:var(--color-accent)}.login-button{width:100%;height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;border:1px solid var(--color-accent);border-radius:5px;color:#04101c;background:var(--color-accent);font:850 .7rem var(--font-display);letter-spacing:.1em;text-transform:uppercase;cursor:pointer;transition:.2s}.login-button svg{width:19px;stroke-width:2}.login-button:hover:not(:disabled){color:white;background:var(--color-accent-hover);transform:translateY(-2px)}.login-button:disabled{opacity:.55;cursor:wait}.security-note{display:flex;align-items:center;justify-content:center;gap:8px;margin:20px 0 0;color:#667582;font:650 .54rem var(--font-display);letter-spacing:.13em;text-transform:uppercase}.security-note span{width:6px;height:6px;border-radius:50%;background:var(--color-accent);box-shadow:0 0 9px rgba(69,183,255,.65)}
@media(max-width:520px){.login-title{font-size:3.7rem}.login-copy{margin-bottom:24px}.form-options{align-items:flex-start}.login-button{height:50px}}
.login-button{position:relative;z-index:1;visibility:visible;opacity:1}
</style>
